<template><section class="task-basics"><h3>基本信息</h3><label>样衣图片</label><div class="task-images"><ImageUpload v-for="(_,i) in images" :key="i" v-model="images[i]" :disabled="readonly" size="lg"/><button v-if="!readonly&&images.length<9" @click="images.push('')">＋ 上传 / 粘贴图片</button></div><div class="task-grid"><label>款号<input class="input" :value="styleNo" disabled/></label><label>类型<input class="input" v-model="basic.type" :disabled="readonly" placeholder="如套装 / 上衣"/></label><label>颜色<input class="input" v-model="basic.colors" :disabled="readonly" placeholder="印花001，款式1"/></label><label>尺码<select class="input" :disabled="readonly" @change="applyTemplate($event)"><option value="">选择尺码模板</option><option v-for="t in templates" :value="t.id" :key="t.id">{{t.name}}</option></select><button v-if="!readonly" @click="saveTemplate">保存尺码模板</button><input class="input" v-model="form.pattern_size" :disabled="readonly" placeholder="以逗号分隔"/></label><label>客户<input class="input" :value="customer" disabled/></label><label>预计单件物料成本<input class="input" :value="cost==null?'—':cost.toFixed(2)+' 元'" disabled/></label><label>单件加工费<input class="input" type="number" min="0" step="0.01" v-model.number="form.price" :disabled="readonly"/></label><label v-for="f in fields" :key="f[0]">{{f[1]}}<input class="input" v-model="basic[f[0]]" :disabled="readonly"/></label><label>标签<input class="input" v-model="form.label_name" :disabled="readonly"/></label><label>预计出版时间<input class="input" type="date" v-model="form.due_date" :disabled="readonly"/></label><label class="task-wide">备注说明<textarea class="input" rows="3" maxlength="500" v-model="form.remark" :disabled="readonly"/></label></div></section></template>
<script setup>
import {computed,ref,onMounted} from 'vue';import ImageUpload from './ImageUpload.vue';import {api} from '../api';
const props=defineProps({form:Object,readonly:Boolean,styleNo:String,customer:String,cost:Number});const templates=ref([]);const fields=[['designer','设计师'],['assistant','设计助理'],['sample_maker','车版师'],['pattern_maker','纸样师'],['salesperson','业务员'],['brand','品牌'],['category','品类']];const basic=computed(()=>props.form.data.basic_info||(props.form.data.basic_info={}));const images=computed(()=>props.form.data.images||(props.form.data.images=[]));
function applyTemplate(e){const t=templates.value.find(t=>String(t.id)===e.target.value);if(t)props.form.pattern_size=(Array.isArray(t.sizes)?t.sizes:[]).map(s=>typeof s==='string'?s:s.name||s.size).filter(Boolean).join(',');}
async function saveTemplate(){const name=prompt('尺码模板名称');if(!name?.trim())return;const sizes=props.form.pattern_size.split(/[,，/、\s]+/).filter(Boolean);if(!sizes.length)return alert('请先填写尺码');try{await api.createSizeTemplate({name:name.trim(),sizes});templates.value=await api.sizeTemplates();}catch(e){alert(e.message);}}
onMounted(async()=>{try{templates.value=await api.sizeTemplates();}catch{templates.value=[];}});
</script><style scoped>.task-basics{border:1px solid var(--line);padding:20px;margin-bottom:20px;background:var(--surface)}h3{margin:0 0 20px}.task-images{display:flex;gap:12px;margin:12px 0 24px;flex-wrap:wrap}.task-images>button{border:1px dashed var(--line);background:var(--surface-2);color:var(--brand);width:130px;cursor:pointer}.task-grid{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:22px}.task-grid label{font-size:12px;display:flex;flex-direction:column;gap:8px;color:var(--ink-soft)}.task-wide{grid-column:1/-1}@media(max-width:1200px){.task-grid{grid-template-columns:repeat(3,minmax(0,1fr))}}</style>
